-- =====================================================================
-- FARM PLAN · 009 · Cargos (descrição do cargo) e Remuneração
-- Base do Contrato de Resultados impresso (modelo da planilha):
--  • cargos: superior imediato, atitudes, experiência e conhecimentos desejáveis…
--  • remuneracao: salário base e % de bonificação por trimestre.
--    Só gestor, administrativo e consultor enxergam (colaborador NÃO vê salário).
-- Traz os dados das abas "Cargos e Funções" e "Equipe" da planilha.
-- Pode rodar mais de uma vez sem problema.
-- =====================================================================
create table if not exists cargos (
  id                    uuid primary key default gen_random_uuid(),
  fazenda_id            uuid not null references fazendas(id) on delete cascade,
  nome                  text not null,
  superior              text,
  funcao_principal      text,
  descricao             text,
  missao                text,
  disponibilidades      text,
  epis                  text,
  formacao              text,
  experiencia           text,
  conhecimentos_obrig   text,
  conhecimentos_desej   text,
  atitudes              text,
  unique (fazenda_id, nome)
);
create table if not exists remuneracao (
  pessoa_id      uuid primary key references pessoas(id) on delete cascade,
  fazenda_id     uuid not null references fazendas(id) on delete cascade,
  salario_base   numeric(12,2),
  bonus_pct      numeric(5,2) not null default 50,   -- % do salário pago por trimestre, conforme a nota
  vinculo        text
);
alter table cargos      enable row level security;
alter table remuneracao enable row level security;
drop policy if exists "ver cargos" on cargos;
drop policy if exists "gerir cargos" on cargos;
drop policy if exists "ver remuneracao" on remuneracao;
drop policy if exists "gerir remuneracao" on remuneracao;
create policy "ver cargos"   on cargos for select using (fazenda_id in (select minhas_fazendas()));
create policy "gerir cargos" on cargos for all using (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']))
                                       with check (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']));
create policy "ver remuneracao"   on remuneracao for select using (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']));
create policy "gerir remuneracao" on remuneracao for all using (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']))
                                            with check (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']));

