-- Confere: cada pessoa com cargo cadastrado e salário
select p.apelido, p.cargo, (c.id is not null) as cargo_tem_descricao, r.salario_base
from pessoas p
left join cargos c on c.fazenda_id = p.fazenda_id and lower(trim(c.nome)) = lower(trim(p.cargo))
left join remuneracao r on r.pessoa_id = p.id
order by p.apelido;